import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.Ci10AEOF.js";const m=JSON.parse('{"title":"Velocity Variable Replacement","description":"Template variable syntax and usage","frontmatter":{"title":"Velocity Variable Replacement","description":"Template variable syntax and usage"},"headers":[],"relativePath":"engine/velocity_variable_replacement.md","filePath":"engine/velocity_variable_replacement.md","lastUpdated":1793057853000}'),n={name:"engine/velocity_variable_replacement.md"};function d(r,e,i,l,c,p){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="velocity-variable-replacement" tabindex="-1">Velocity Variable Replacement <a class="header-anchor" href="#velocity-variable-replacement" aria-label="Permalink to &quot;Velocity Variable Replacement&quot;">​</a></h1><p>OIE replaces <code>${...}</code> references with <strong>Apache Velocity</strong> in connector settings and alert templates: templates, file names, directory paths, URLs, headers, and the other fields listed under <a href="#where-velocity-is-used">Where Velocity is used</a>. It does not replace them in filter or transformer code. A <code>${name}</code> inside a JavaScript step, a Mapper mapping or a Message Builder mapping stays as literal text; read the value with <code>$(&#39;name&#39;)</code> or the map&#39;s <code>get</code> instead.</p><h2 id="basic-syntax" tabindex="-1">Basic syntax <a class="header-anchor" href="#basic-syntax" aria-label="Permalink to &quot;Basic syntax&quot;">​</a></h2><p>Variables stored in maps are referenced using the <code>${}</code> syntax:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>${variableName}</span></span></code></pre></div><p>This pulls the value from the variable maps (see <a href="#variable-map-priority">Variable Map Priority</a> below).</p><p>A key you name yourself, such as <code>patientId</code>, is in a map only because a transformer step stored it: a <a href="./filters_and_transformers.html#mapper-step">Mapper step</a> writes to the map chosen by its scope setting (the channel map by default), and a JavaScript step calls <code>channelMap.put(&#39;patientId&#39;, value)</code>.</p><h2 id="variable-map-priority" tabindex="-1">Variable map priority <a class="header-anchor" href="#variable-map-priority" aria-label="Permalink to &quot;Variable map priority&quot;">​</a></h2><p>When you reference <code>${variableName}</code> in a message-level field, OIE loads all variable maps into a single Velocity context. Maps loaded later overwrite earlier values for the same key, so later maps have higher priority. The effective priority from highest to lowest is:</p><ol><li><strong>Response Map</strong>: Destination response data</li><li><strong>Connector Map</strong>: Variables scoped to the current connector</li><li><strong>Channel Map</strong>: Variables scoped to the current message across all connectors</li><li><strong>Source Map</strong>: Variables populated by the source connector (e.g., remote address, original filename)</li><li><strong><a href="./glossary.html#global-channel-map">Global Channel Map</a></strong>: Variables shared across all messages in this channel</li><li><strong>Global Map</strong>: Variables shared across all channels</li><li><strong>Configuration Map</strong>: Server-wide key-value pairs from Settings</li></ol><p>If no match is found, the literal string <code>${variableName}</code> is output.</p><p>The list applies to message-level fields. An alert template gets the alert&#39;s own variables, the utility variables below, and the global and configuration maps, but no message maps or global channel map. The alert variables are listed under <a href="./alerts_and_notifications.html#alert-variables">Alert variables</a>.</p><p>A template with a Velocity syntax error is not replaced at all: the engine uses the field&#39;s text as written. It logs <code>Could not replace template values</code> at WARN, but with the shipped logging configuration that line does not appear; the server log shows Velocity&#39;s own error line instead.</p><p>Replacement runs only on text that contains a <code>$</code>. A field with <code>#if</code> or <code>#foreach</code> but no <code>$</code> anywhere is used exactly as typed.</p><h2 id="standard-variables-and-templates" tabindex="-1">Standard variables and templates <a class="header-anchor" href="#standard-variables-and-templates" aria-label="Permalink to &quot;Standard variables and templates&quot;">​</a></h2><p>The utility variables <code>date</code>, <code>DATE</code>, <code>COUNT</code>, <code>UUID</code> and <code>SYSTIME</code> go into the context first, so a key with the same name in any map replaces them. <code>message</code>, <code>channelId</code>, <code>channelName</code> and <code>HASH</code> go in after the configuration, global and global channel maps and before the source, channel, connector and response maps, so only a key in one of those four per-message maps replaces them. <code>originalFilename</code> is set to its timestamp default only when no map supplied one. The <code>message</code> properties, <code>${HASH}</code> and <code>${originalFilename}</code> exist only when a template is replaced for a connector message, as the destination connector fields in the examples below are. A field replaced without a message, such as the File Reader directory, gets the utility variables, <code>${channelId}</code>, <code>${channelName}</code>, and the global channel, global and configuration maps only. There <code>${channelId}</code> and <code>${channelName}</code> go in before the global channel map, so a global channel map key with the same name replaces them.</p><h3 id="message-properties" tabindex="-1">Message properties <a class="header-anchor" href="#message-properties" aria-label="Permalink to &quot;Message properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${message.messageId}</code></td><td>The current message ID</td></tr><tr><td><code>${message.encodedData}</code></td><td>The encoded (outbound) message content</td></tr><tr><td><code>${message.rawData}</code></td><td>The raw inbound message content</td></tr><tr><td><code>${message.transformedData}</code></td><td>The transformed message content</td></tr><tr><td><code>${message.channelId}</code></td><td>The channel ID for this message</td></tr><tr><td><code>${message.channelName}</code></td><td>The channel name for this message</td></tr><tr><td><code>${message.connectorName}</code></td><td>The name of the current connector</td></tr><tr><td><code>${message.metaDataId}</code></td><td>The metadata ID of the current connector</td></tr><tr><td><code>${channelId}</code></td><td>The current channel&#39;s UUID</td></tr><tr><td><code>${channelName}</code></td><td>The current channel&#39;s name</td></tr></tbody></table><h3 id="utility-variables" tabindex="-1">Utility variables <a class="header-anchor" href="#utility-variables" aria-label="Permalink to &quot;Utility variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${date.get(&#39;yyyyMMdd&#39;)}</code></td><td>Current date/time formatted with a Java <code>SimpleDateFormat</code> pattern</td></tr><tr><td><code>${DATE}</code></td><td>Current timestamp formatted as <code>dd-MM-yy_HH-mm-ss.SS</code></td></tr><tr><td><code>${COUNT}</code></td><td>A counter that goes up by one each time it is referenced. It belongs to the connector doing the replacement, starts at 1, and starts again after a redeploy</td></tr><tr><td><code>${UUID}</code></td><td>A random UUID string</td></tr><tr><td><code>${SYSTIME}</code></td><td>Current system time in milliseconds</td></tr><tr><td><code>${HASH}</code></td><td>SHA-256 hash of the encoded message content (falls back to raw if encoded is unavailable)</td></tr><tr><td><code>${originalFilename}</code></td><td>Original filename from the source connector (defaults to <code>&lt;timestamp&gt;.dat</code> if unset)</td></tr><tr><td><code>${XmlUtil}</code></td><td>The <code>XmlUtil</code> script class, for static calls such as <code>${XmlUtil.encode($value)}</code></td></tr><tr><td><code>${JsonUtil}</code></td><td>The <code>JsonUtil</code> script class, for static calls such as <code>${JsonUtil.escape($value)}</code></td></tr><tr><td><code>${maps.get(&#39;key&#39;)}</code></td><td>The value of a key from the first loaded map that has it. Maps load from the configuration map toward the response map, so this returns the lowest-priority match</td></tr></tbody></table><h3 id="date-formatting-examples" tabindex="-1">Date formatting examples <a class="header-anchor" href="#date-formatting-examples" aria-label="Permalink to &quot;Date formatting examples&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>${date.get(&#39;yyyyMMdd&#39;)}          → 20240101</span></span>\n<span class="line"><span>${date.get(&#39;yyyy-MM-dd HH:mm&#39;)} → 2024-01-01 12:00</span></span>\n<span class="line"><span>${date.get(&#39;yyyyMMddHHmmss&#39;)}   → 20240101120000</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Each example is a destination connector field, replaced for each message with that message&#39;s maps in the context. <code>message</code> and <code>date</code> are the built-in objects listed above. <code>patientId</code>, <code>patientLastName</code>, <code>patientFirstName</code> and <code>medicalRecordNumber</code> are keys a transformer step stored in the channel map.</p><p><strong>In a File Writer filename:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>message_${message.messageId}_${date.get(&#39;yyyyMMdd&#39;)}.hl7</span></span></code></pre></div><p><strong>In an HTTP Sender URL:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.example.com/patients/${patientId}/records</span></span></code></pre></div><p><strong>In a destination template:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Patient: ${patientLastName}, ${patientFirstName}</span></span>\n<span class="line"><span>MRN: ${medicalRecordNumber}</span></span></code></pre></div><h2 id="conditional-statements" tabindex="-1">Conditional statements <a class="header-anchor" href="#conditional-statements" aria-label="Permalink to &quot;Conditional statements&quot;">​</a></h2><p>Velocity supports <code>#if</code> / <code>#else</code> / <code>#elseif</code> / <code>#end</code> for conditional logic within templates. <code>gender</code> here is a channel map key stored by a transformer step. A key that is in none of the maps compares as not equal, so the <code>#else</code> branch is taken and no error is raised:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#if(${gender} == &quot;M&quot;)</span></span>\n<span class="line"><span>Male</span></span>\n<span class="line"><span>#elseif(${gender} == &quot;F&quot;)</span></span>\n<span class="line"><span>Female</span></span>\n<span class="line"><span>#else</span></span>\n<span class="line"><span>Unknown</span></span>\n<span class="line"><span>#end</span></span></code></pre></div><h2 id="for-loops" tabindex="-1">For loops <a class="header-anchor" href="#for-loops" aria-label="Permalink to &quot;For loops&quot;">​</a></h2><p>Velocity supports <code>#foreach</code> loops for iterating over collections. <code>itemList</code> must be a collection a transformer step stored in a map: a JavaScript array and a <code>java.util.List</code> both iterate. If the key is missing, or its value is not a collection (a string, for example), the loop produces no output and no error. <code>${item}</code> and <code>$item</code> are the same reference; the braces only mark where the name ends:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#foreach(${item} in ${itemList})</span></span>\n<span class="line"><span>Item: ${item}</span></span>\n<span class="line"><span>#end</span></span></code></pre></div><h2 id="where-velocity-is-used" tabindex="-1">Where Velocity is used <a class="header-anchor" href="#where-velocity-is-used" aria-label="Permalink to &quot;Where Velocity is used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Example</th></tr></thead><tbody><tr><td><strong>Destination templates</strong></td><td>Message body content</td></tr><tr><td><strong>File Writer directory/filename</strong></td><td><code>/output/${channelName}/${date.get(&#39;yyyyMMdd&#39;)}/</code></td></tr><tr><td><strong>HTTP Sender URL</strong></td><td><code>https://host/api/${patientId}</code></td></tr><tr><td><strong>HTTP headers/parameters</strong></td><td>Header values with dynamic content</td></tr><tr><td><strong>Email subject/body</strong></td><td>SMTP sender fields</td></tr><tr><td><strong>Database Reader and Writer SQL</strong></td><td>Each <code>${}</code> becomes a <code>?</code> bound as a JDBC parameter, not text. Write <code>${patientId}</code>, not <code>&#39;${patientId}&#39;</code>, and a <code>${}</code> cannot supply a table or column name. A <code>${}</code> that matches nothing is bound as the text <code>${name}</code> itself</td></tr><tr><td><strong>Alert templates</strong></td><td>Alert notification content</td></tr></tbody></table><p>In the Database Reader the select runs before any message exists, so its values come from the utility variables and the global channel, global and configuration maps. The post-process statement also sees the row&#39;s columns, as <code>${column_name}</code>, and the processed message when there is one.</p><h2 id="velocity-vs-javascript" tabindex="-1">Velocity vs. JavaScript <a class="header-anchor" href="#velocity-vs-javascript" aria-label="Permalink to &quot;Velocity vs. JavaScript&quot;">​</a></h2><p>How the two compare:</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Velocity <code>${}</code></th><th>JavaScript</th></tr></thead><tbody><tr><td><strong>Syntax</strong></td><td><code>${varName}</code></td><td><code>channelMap.get(&#39;varName&#39;)</code></td></tr><tr><td><strong>Where</strong></td><td>Template fields, filenames, URLs</td><td>Transformer/filter steps, scripts</td></tr><tr><td><strong>Conditionals</strong></td><td><code>#if/#else/#end</code></td><td><code>if/else</code></td></tr><tr><td><strong>Loops</strong></td><td><code>#foreach</code></td><td><code>for</code>, <code>while</code></td></tr></tbody></table>',42)]))}const g=t(n,[["render",d]]);export{m as __pageData,g as default};
